from base_sensor import BaseVirtualSensor

class TMP461_Simulator(BaseVirtualSensor):
    REG_WIDTH = 8
    READ_ONLY_FIELDS = ['BUSY', 'LHIGH', 'LLOW', 'RHIGH', 'RLOW', 'OPEN', 'RTHRM', 'LTHRM', 'FIXED_1']
    READ_TO_CLEAR_FIELDS = ['LHIGH', 'LLOW', 'RHIGH', 'RLOW', 'OPEN', 'RTHRM', 'LTHRM']

    def __init__(self):
        super().__init__()
        self.regs = {i: 0 for i in range(256)}  # Initialize all registers to 0
        self.regs[0x02] = 0x80  # Set BUSY bit to 1

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if nbytes == 1:
            return (self.regs[0x02] << 8) & 0xFF00  # Return only bits 15:8 for single byte access
        return self.regs[addr]

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr == 0x0F:  # One-Shot register
            self.regs[0x02] = 0x80  # Set BUSY bit to 1
        elif addr in [0x03, 0x09]:  # Config register
            self.regs[0x02] = 0x00  # Clear BUSY bit
        elif addr in [0x16]:  # Channel enable register
            self.regs[0x02] &= 0x7F  # Clear BUSY bit
        else:
            if addr in [f['bits'].split(':')[0] for f in self.READ_ONLY_FIELDS]:
                return  # Ignore writes to read-only fields
            self.regs[addr] = data
            if addr in [f['bits'].split(':')[0] for f in self.READ_TO_CLEAR_FIELDS]:
                self.regs[0x02] &= ~(1 << int(addr))  # Clear the corresponding bit in the status register

